using sv_e63d906d3ca84fe2ba73f697c166d5d0.Models;

namespace sv_e63d906d3ca84fe2ba73f697c166d5d0.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with fresh mozzarella, basil, and San Marzano tomatoes.", 30),
            new(2, "Carbonara", "Traditional Roman pasta with guanciale, egg yolk, Pecorino Romano, and black pepper.", 25),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream and cocoa powder.", 45),
            new(4, "Risotto alla Milanese", "Creamy saffron-infused Arborio rice cooked slowly in broth.", 40),
        },
        [2] = new List<Recipe>
        {
            new(5, "Pad Thai", "Stir-fried rice noodles with shrimp, tofu, peanuts, and tamarind sauce.", 35),
            new(6, "Green Curry", "Aromatic coconut milk curry with Thai basil, bamboo shoots, and chicken.", 40),
            new(7, "Tom Yum Soup", "Spicy and sour soup with lemongrass, galangal, kaffir lime leaves, and prawns.", 25),
            new(8, "Mango Sticky Rice", "Sweet glutinous rice with fresh mango slices and coconut cream.", 50),
        },
        [3] = new List<Recipe>
        {
            new(9, "Tacos al Pastor", "Marinated pork tacos with pineapple, cilantro, and onion on corn tortillas.", 60),
            new(10, "Guacamole", "Fresh avocado dip with lime juice, cilantro, jalapeño, and tomato.", 10),
            new(11, "Churros", "Fried dough pastry coated in cinnamon sugar, served with chocolate sauce.", 35),
            new(12, "Enchiladas Verdes", "Corn tortillas filled with chicken, covered in tangy tomatillo salsa verde.", 45),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow API call
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_e63d906d3ca84fe2ba73f697c166d5d0.Models
@using sv_e63d906d3ca84fe2ba73f697c166d5d0.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@implements IDisposable

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_error</p>
        <button class="btn btn-outline-danger" @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p class="text-muted"><small>Refreshing…</small></p>
    }

    <table class="table">
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time (min)</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in GetSortedRecipes())
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private string? _error;
    private bool _isRefreshing;
    private int _loadedCuisineId;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        // Only reload when the cuisine changes, not when sort changes
        if (_loadedCuisineId == CuisineId && _recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request
        await CancelPendingRequestAsync();

        _cts = new CancellationTokenSource();
        var cancellationToken = _cts.Token;
        var requestedCuisineId = CuisineId;

        // Determine loading state
        if (_recipes is not null)
        {
            _isRefreshing = true;
        }

        _error = null;

        try
        {
            var results = await RecipeService.GetByCuisineAsync(requestedCuisineId, cancellationToken);

            // Only apply results if this request wasn't cancelled
            if (!cancellationToken.IsCancellationRequested)
            {
                _recipes = results;
                _loadedCuisineId = requestedCuisineId;
                _isRefreshing = false;
            }
        }
        catch (OperationCanceledException)
        {
            // Request was cancelled (user navigated to different cuisine or left page) — do nothing
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", requestedCuisineId);
            _isRefreshing = false;
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", requestedCuisineId);
            _isRefreshing = false;
            _error = "Something went wrong while loading recipes. Please try again.";
        }
    }

    private IEnumerable<Recipe> GetSortedRecipes()
    {
        if (_recipes is null) return Enumerable.Empty<Recipe>();

        return Sort?.ToLowerInvariant() switch
        {
            "newest" => _recipes.OrderByDescending(r => r.Id),
            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes),
            _ => _recipes
        };
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    private async Task CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

